operations.schema:
input SetQuestionInput {
  question: String!
  context: String
}

operations.reducer:
const { question, context } = action.input;
state.question = question;
if (context !== undefined) state.context = context;

operations.schema:
input AnswerDecisionInput {
  answer: String!
  answeredBy: EthereumAddress!
  answeredAt: DateTime!
}

operations.reducer:
const { answer, answeredBy, answeredAt } = action.input;
if (state.status !== "OPEN")
  throw new DecisionNotOpenError("Only an open decision can be answered");
if (answer.trim() === "")
  throw new AnswerRequiredError("The answer needs text");
state.status = "ANSWERED";
state.answer = answer;
state.answeredBy = answeredBy;
state.answeredAt = answeredAt;

if (state.status !== "ANSWERED")
  throw new DecisionNotAnsweredError(
    "Only an answered decision can be reopened",
  );
state.status = "OPEN";
state.answer = null;
state.answeredBy = null;
state.answeredAt = null;
state.reason = action.input.reason ?? null;

if (state.status !== "OPEN")
  throw new DecisionNotOpenError("Only an open decision can be withdrawn");
state.status = "WITHDRAWN";
state.reason = action.input.reason ?? null;

operations.schema:
input AddReferenceInput {
  id: OID!
  kind: ReferenceKind!
  documentId: PHID!
  title: String!
}

operations.reducer:
const { id, kind, documentId, title } = action.input;
if (state.references.some((reference) => reference.id === id))
  throw new DuplicateReferenceIdError(`Reference ${id} already exists`);
{
  const existing = state.references.find(
    (reference) =>
      reference.documentId === documentId && reference.kind === kind,
  );
  if (existing)
    throw new DuplicateReferenceError(
      `"${existing.title}" is already linked.`,
    );
}
state.references.push({ id, kind, documentId, title });

const index = state.references.findIndex(
  (reference) => reference.id === action.input.id,
);
if (index === -1)
  throw new ReferenceNotFoundError(
    `Reference ${action.input.id} not found`,
  );
state.references.splice(index, 1);
